class Reviewer(Executor):
    def __init__(self):
        super().__init__(id='reviewer')

    @handler
    async def start(self, draft: str, ctx: WorkflowContext[str, str]) -> None:
        await ctx.request_info(request_data=ReviewRequest(draft), response_type=bool)

    @response_handler
    async def on_review(self, original: ReviewRequest, approved: bool,
                        ctx: WorkflowContext[str, str]) -> None:
        await ctx.yield_output('published' if approved else 'rejected')

